import{_ as t,a,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Build with AI","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai/index.md","filePath":"api/build-with-ai/index.md","lastUpdated":1786429091000}'),n={name:"api/build-with-ai/index.md"};function r(d,e,s,l,h,c){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="build-with-ai" tabindex="-1">Build with AI <a class="header-anchor" href="#build-with-ai" aria-label="Permalink to &quot;Build with AI&quot;">​</a></h1><p>This documentation is built to be consumed by AI coding agents (Claude Code, Codex, Antigravity, and other MCP-capable editors) as well as humans. If you are building a storefront or an app on the Bagisto API — or extending the API itself — with an AI assistant, point it at the resources on this page.</p><p>Three things make an agent productive here, in order of how much they help:</p><table tabindex="0"><thead><tr><th>Resource</th><th>What it gives the agent</th><th>Page</th></tr></thead><tbody><tr><td><strong>Agent Skills</strong></td><td>The full build playbook — call sequences, gotchas (token model, <code>id</code> vs <code>_id</code>, filters) baked in, so the agent doesn&#39;t rediscover them</td><td><a href="/api/build-with-ai/agent-skills.html">Agent Skills</a></td></tr><tr><td><strong>LLM Index</strong></td><td>A one-fetch machine index (<code>llms.txt</code>) of every endpoint, grouped by surface + transport</td><td><a href="/api/build-with-ai/#llm-index">Build with AI</a></td></tr><tr><td><strong>MCP Server</strong> <em>(optional)</em></td><td>Live doc search from inside the editor while coding</td><td><a href="/api/build-with-ai/mcp-server.html">MCP Server</a></td></tr></tbody></table><h2 id="llm-index" tabindex="-1">LLM Index <a class="header-anchor" href="#llm-index" aria-label="Permalink to &quot;LLM Index&quot;">​</a></h2><p>A single file lists every documented endpoint with a one-line description and a link, so an agent can discover the whole API surface in one fetch:</p><ul><li><strong>Index:</strong> <a href="/llms.txt"><code>/llms.txt</code></a> — every Shop and Admin endpoint, grouped by transport and menu.</li><li><strong>Full content:</strong> <a href="/llms-full.txt"><code>/llms-full.txt</code></a> — the complete documentation concatenated into one file for full ingestion.</li></ul><p>These follow the <a href="https://llmstxt.org" target="_blank" rel="noreferrer">llms.txt convention</a>. The index opens with a <strong>Shop vs Admin</strong> primer and two cross-cutting references every agent should read first — <a href="/api/authentication.html">Authentication</a> and <a href="/api/graphql-api/identifiers.html">Identifiers</a>.</p><h2 id="where-an-agent-should-start" tabindex="-1">Where an agent should start <a class="header-anchor" href="#where-an-agent-should-start" aria-label="Permalink to &quot;Where an agent should start&quot;">​</a></h2><ol><li><strong><a href="/api/authentication.html">Authentication</a></strong> and the <a href="/api/workflows/shop/">Storefront</a> overview — the credential model and the surface it is about to work on.</li><li><strong><a href="/llms.txt"><code>/llms.txt</code></a></strong> — discover the exact endpoint needed.</li><li>That endpoint&#39;s page — the exact request body, response shape, and errors. <strong>Never guess a payload.</strong></li><li>For end-to-end flows, the <a href="/api/workflows/">Workflows</a> — ordered walkthroughs that chain real endpoint calls.</li></ol><p>Mind the GraphQL rules: on action mutations select <strong>result fields</strong> (<code>cartId</code>, <code>orderId</code>, <code>success</code>) — not <code>id</code>; inputs are camelCase; the Shop and Admin GraphQL endpoints are separate (<code>/api/graphql</code> vs <code>/api/admin/graphql</code>).</p><h2 id="two-ways-to-give-the-agent-this-knowledge" tabindex="-1">Two ways to give the agent this knowledge <a class="header-anchor" href="#two-ways-to-give-the-agent-this-knowledge" aria-label="Permalink to &quot;Two ways to give the agent this knowledge&quot;">​</a></h2><ul><li><strong><a href="/api/build-with-ai/agent-skills.html">Agent Skills</a></strong> — install packaged build-rules once; the agent then knows the storefront flows, the auth model, and the transport gotchas without you pasting context. <strong>Start here.</strong></li><li><strong><a href="/api/build-with-ai/mcp-server.html">MCP Server</a></strong> <em>(optional)</em> — let the agent search these docs on demand from inside the editor. Useful alongside the skills; not required, since <code>llms.txt</code> covers the same need statically.</li></ul>',13)]))}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
